local GardenRakeMaker = {}
local PRODUCTS = {
    iron_gardenrake = { name = "Železni vrtna grelda", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtna grelda za vrtnarje." },
    bronze_gardenrake = { name = "Bronast vrtna grelda", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtna grelda za vrtnarje." },
    silver_gardenrake = { name = "Srebrn vrtna grelda", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtna grelda za vrtnarje." },
    gilded_gardenrake = { name = "Pozlačen vrtna grelda", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtna grelda za vrtnarje." },
    jewel_set_gardenrake = { name = "Draguljast vrtna grelda", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtna grelda za vrtnarje." },
    royal_sovereign_gardenrake = { name = "Kraljevski suveren vrtna grelda", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtna grelda z biseri za krono." },
}
local BUILDINGS = {
    gardenrake_workshop = { name = "Gardenrake delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardenrake_house = { name = "Gardenrake hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardenrake_atelier = { name = "Mojstrski gardenrake atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardenrake_palace = { name = "Suverena gardenrake palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenRakeMaker.ironStock=14; GardenRakeMaker.bronzeStock=12; GardenRakeMaker.woodStock=14; GardenRakeMaker.leatherStock=10; GardenRakeMaker.silverStock=8; GardenRakeMaker.goldStock=6; GardenRakeMaker.jewelStock=4; GardenRakeMaker.pearlStock=4
GardenRakeMaker.productStock = {}; GardenRakeMaker.buildings = {}; GardenRakeMaker.maker = nil; GardenRakeMaker.activeMaking = {}; GardenRakeMaker.totalProducts = 0; GardenRakeMaker.dayTimer = 0
function GardenRakeMaker.init() GardenRakeMaker.ironStock=14; GardenRakeMaker.bronzeStock=12; GardenRakeMaker.woodStock=14; GardenRakeMaker.leatherStock=10; GardenRakeMaker.silverStock=8; GardenRakeMaker.goldStock=6; GardenRakeMaker.jewelStock=4; GardenRakeMaker.pearlStock=4; GardenRakeMaker.productStock={}; GardenRakeMaker.buildings={}; GardenRakeMaker.maker=nil; GardenRakeMaker.activeMaking={}; GardenRakeMaker.totalProducts=0; GardenRakeMaker.dayTimer=0; print("[GardenRakeMaker] Royal Garden Rake Maker System initialized (6 products, 4 buildings)") end
function GardenRakeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenRakeMaker.maker={name=n or ("Gredlar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gredlar najet: %s (spretnost: %d)",GardenRakeMaker.maker.name,s),"success") end; return true end
function GardenRakeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenRakeMaker.build(id) local ok,e=GardenRakeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenRakeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenRakeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenRakeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenRakeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenRakeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenRakeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenRakeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenRakeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenRakeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenRakeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenRakeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenRakeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenRakeMaker.buildings==0 then return false,"Potrebna gredlarska delavnica" end; if not GardenRakeMaker.maker then return false,"Potreben gredlar" end; return true end
function GardenRakeMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenRakeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenRakeMaker.ironStock=GardenRakeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenRakeMaker.bronzeStock=GardenRakeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenRakeMaker.woodStock=GardenRakeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenRakeMaker.leatherStock=GardenRakeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenRakeMaker.silverStock=GardenRakeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenRakeMaker.goldStock=GardenRakeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenRakeMaker.jewelStock=GardenRakeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenRakeMaker.pearlStock=GardenRakeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenRakeMaker.maker then t=math.max(1,t-math.floor(GardenRakeMaker.maker.skill/13)) end; table.insert(GardenRakeMaker.activeMaking,{id="gardenrake_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenRakeMaker.completeMaking(m) local q=1.0+(GardenRakeMaker.getQualityBonus()/100); if GardenRakeMaker.maker then q=q+(GardenRakeMaker.maker.skill/140) end; q=math.min(2.5,q); GardenRakeMaker.productStock[m.productType]=(GardenRakeMaker.productStock[m.productType] or 0)+m.quantity; GardenRakeMaker.totalProducts=GardenRakeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenRakeMaker.maker then GardenRakeMaker.maker.itemsMade=GardenRakeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenRakeMaker.maker.skill=math.min(100,GardenRakeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Grelda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenrake.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenRakeMaker.update(dt) if not _G.state then return end; GardenRakeMaker.dayTimer=GardenRakeMaker.dayTimer+dt; if GardenRakeMaker.dayTimer>=30 then GardenRakeMaker.dayTimer=0; for i=#GardenRakeMaker.activeMaking,1,-1 do local m=GardenRakeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenRakeMaker.completeMaking(m); table.remove(GardenRakeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenRakeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenRakeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenRakeMaker.getStats() return {ironStock=GardenRakeMaker.ironStock,bronzeStock=GardenRakeMaker.bronzeStock,woodStock=GardenRakeMaker.woodStock,leatherStock=GardenRakeMaker.leatherStock,silverStock=GardenRakeMaker.silverStock,goldStock=GardenRakeMaker.goldStock,jewelStock=GardenRakeMaker.jewelStock,pearlStock=GardenRakeMaker.pearlStock,productStock=GardenRakeMaker.productStock,numBuildings=#GardenRakeMaker.buildings,hasMaker=GardenRakeMaker.maker~=nil,makerName=GardenRakeMaker.maker and GardenRakeMaker.maker.name or "—",makerSkill=GardenRakeMaker.maker and GardenRakeMaker.maker.skill or 0,activeMaking=#GardenRakeMaker.activeMaking,totalProducts=GardenRakeMaker.totalProducts} end
return GardenRakeMaker
